pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 block1, uint256 block2) public {
        // restrict blocks to admissible range and ensure block1 < block2
        bound(block1, 1, 1e9);
        bound(block2, block1 + 1, 1e9);
        uint256 amount = 10 ether;

        // call 1 at block1
        vm.roll(block1);
        vm.warp(block1 + 1000);
        address actor = makeAddr("actor");
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: amount}("");
        require(ok1, "call1 failed");
        uint256 pastBlockTime1 = c.pastBlockTime();

        // call 2 at block2
        vm.roll(block2);
        vm.warp(block2 + 1000);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: amount}("");
        require(ok2, "call2 failed");
        uint256 pastBlockTime2 = c.pastBlockTime();

        // General rule: pastBlockTime after call 2 must be greater than after call 1
        assertTrue(pastBlockTime2 > pastBlockTime1);
    }
}

