pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 blockNum1, uint128 blockNum2, uint128 ts1, uint128 ts2) public {
        // Ensure blockNum2 > blockNum1 and both are valid block numbers (non-zero)
        vm.assume(blockNum2 > blockNum1);
        vm.assume(blockNum1 > 0);
        // Ensure timestamps are consistent with increasing block numbers
        vm.assume(ts2 > ts1);

        // First call
        vm.roll(blockNum1);
        vm.warp(ts1);
        vm.deal(address(this), 10 ether);
        try c.fallback{value: 10 ether}() {
            // success
        } catch {
            // If first call reverts, skip test
            return;
        }
        bool firstZero = address(c).balance == 0;

        // Second call
        vm.roll(blockNum2);
        vm.warp(ts2);
        vm.deal(address(this), 10 ether);
        try c.fallback{value: 10 ether}() {
            // success
        } catch {
            // If second call reverts, skip test
            return;
        }
        bool secondZero = address(c).balance == 0;

        // Property: after the second call, balance is zero iff (blockNum2 - 1) % 15 == 0
        // Note: pastBlockTime = ts1 + 1 after first call, and ts2 > ts1 ensures ts2 > pastBlockTime, so second call succeeds.
        // The divisor change from 15 to 16 makes this condition fail for some blockNum1/blockNum2 values.
        assertTrue(secondZero == ((blockNum2 - 1) % 15 == 0));
    }
}

