pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum) public {
        // Restrict to relevant block numbers where the contract can be called
        vm.assume(blockNum > 0 && blockNum < 1e9);

        // Fund an EOA with exactly 10 ether
        address caller = address(0xdead);
        vm.deal(caller, 10 ether);

        // Set block number and warp to a fresh timestamp (pastBlockTime is initially 0, timestamp > 0 passes)
        vm.roll(blockNum);
        vm.warp(blockNum);

        // Execute the fallback call
        vm.prank(caller);
        c.fallback{value: 10 ether}();

        // After the call, the balance should be zero iff blockNum is divisible by 15
        bool divisibleBy15 = (blockNum % 15 == 0);
        bool balanceZero = address(c).balance == 0;
        assertTrue(balanceZero == divisibleBy15);
    }
}

