pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockTime, uint256 callValue, uint256 blockNum1, uint256 blockNum2) public {
        vm.assume(blockTime > 0);
        vm.assume(callValue == 10 ether);
        vm.assume(blockNum1 != blockNum2);

        // First call: set up time and block number, then call fallback
        vm.deal(address(this), callValue);
        vm.warp(blockTime);
        vm.roll(blockNum1);
        (bool ok1,) = address(c).call{value: callValue}("");
        vm.assume(ok1); // ensure first call succeeded

        // Second call: advance time only by a small amount so the gate must be satisfied by the update
        uint256 secondTime = blockTime + 1;
        vm.warp(secondTime);
        vm.roll(blockNum2);
        vm.deal(address(this), callValue);
        (bool ok2,) = address(c).call{value: callValue}("");

        // The reference updates pastBlockTime to block.timestamp+1, so second call succeeds.
        // The buggy version leaves pastBlockTime unchanged, so require(block.timestamp > pastBlockTime) fails.
        assertTrue(ok2);
    }
}

