pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 etherAmount, uint256 warpSeconds) public {
        // bound ether to a range that includes both 1 and 10 ether
        etherAmount = bound(etherAmount, 0.1 ether, 20 ether);
        // ensure we have a future timestamp after pastBlockTime
        warpSeconds = bound(warpSeconds, 1, 365 days);

        address sender = address(0x1234);
        vm.deal(sender, etherAmount);
        vm.prank(sender);

        vm.warp(block.timestamp + warpSeconds);

        bool ok;
        try c.fallback{value: etherAmount}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // if call succeeded, the contract must hold exactly the sent amount
            // (since pastBlockTime is set to block.timestamp+1, no further calls can succeed)
            // The reference only succeeds for exactly 10 ether, so it will hold etherAmount only when etherAmount == 10 ether.
            // The mutant only succeeds for exactly 1 ether. So if the fuzzer picks etherAmount == 1 ether,
            // the mutant holds 1 ether while the reference would hold 0 (call reverts) or 10 ether (if it were 10 ether).
            assertEq(address(c).balance, etherAmount, "Contract balance must equal sent amount on success");
        }
    }
}

