pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 warpDelta, uint256 blockNum) public {
        // Restrict msg.value to a reasonable range to avoid overflow and keep fuzzing efficient
        vm.assume(amount <= 1000 ether);
        // Ensure warpDelta > 0 so timestamp strictly increases
        vm.assume(warpDelta > 0 && warpDelta <= 365 days);
        // Set block number to a reasonable value
        vm.roll(blockNum);
        // Advance time so block.timestamp > pastBlockTime initially (pastBlockTime defaults to 0)
        vm.warp(block.timestamp + warpDelta);

        // Fund and call from an arbitrary EOA
        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.prank(actor);

        uint256 balanceBefore = address(c).balance;

        // We want to observe the contract's balance change when a call succeeds.
        // We wrap the fallback call in a try/catch to know if it reverted.
        bool ok;
        try c.fallback{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;

        // GENERAL RULE: If the call succeeded (did not revert), the balance must increase by exactly 10 ether.
        // The reference satisfies this because it requires msg.value == 10 ether.
        // The mutant (which requires 1 ether) will fail this assertion when amount is 1 ether and the call succeeds.
        assertTrue(!ok || balanceAfter == balanceBefore + 10 ether);
    }
}
